package org.surface.sq2.usbtest;
import android.app.Activity;
import android.os.*;
import android.media.*;
import android.widget.*;
import android.util.Log;
import org.json.*;
import java.io.*;

public class MainActivity extends Activity {
 TextView status; volatile boolean cancel,busy; AudioManager am;
 void show(String s){Log.i("SQ2UsbAudio",s);runOnUiThread(()->status.setText(s));}
 boolean usb(AudioDeviceInfo d){return d!=null&&(d.getType()==AudioDeviceInfo.TYPE_USB_HEADSET||d.getType()==AudioDeviceInfo.TYPE_USB_DEVICE);}
 AudioDeviceInfo find(boolean input){for(AudioDeviceInfo d:am.getDevices(input?AudioManager.GET_DEVICES_INPUTS:AudioManager.GET_DEVICES_OUTPUTS))if(usb(d))return d;throw new IllegalStateException("No USB "+(input?"input":"output")+"; NO fallback permitted");}
 void save(String op,JSONObject j)throws Exception {try(FileOutputStream f=new FileOutputStream(new File(getFilesDir(),"result-"+op+".json"))){f.write(j.toString(2).getBytes("UTF-8"));f.getFD().sync();}show(j.toString());}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(128);am=getSystemService(AudioManager.class);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(28,40,28,20);status=new TextView(this);status.setTextSize(19);l.addView(status);for(String op:new String[]{"probe","tone","roundtrip"}){Button x=new Button(this);x.setText(op.equals("tone")?"耳机左/右低音量测试":op.equals("roundtrip")?"USB麦克风录音5秒并从耳机回放":"查看USB设备");x.setOnClickListener(v->run(op));l.addView(x);}setContentView(l);String op=getIntent().getStringExtra("op");run(op==null?"probe":op);}
 void run(String op){if(busy)return;busy=true;cancel=false;new Thread(()->{JSONObject j=new JSONObject();try{j.put("op",op);j.put("boot_id",read("/proc/sys/kernel/random/boot_id"));if(op.equals("probe")){JSONArray a=new JSONArray();for(AudioDeviceInfo d:am.getDevices(AudioManager.GET_DEVICES_ALL)){JSONObject e=new JSONObject();e.put("id",d.getId());e.put("type",d.getType());e.put("name",d.getProductName());e.put("address",d.getAddress());e.put("source",d.isSource());e.put("sink",d.isSink());a.put(e);}j.put("devices",a);j.put("usb_output_id",find(false).getId());j.put("usb_input_id",find(true).getId());}else if(op.equals("tone")||op.equals("auto-tone")){short[] p=new short[48000*4*2];for(int n=0;n<48000*4;n++){double edge=Math.min(1,Math.min((n%96000)/480.0,(95999-n%96000)/480.0));short v=(short)(2000*Math.max(0,edge)*Math.sin(2*Math.PI*440*n/48000));p[2*n+(n<96000?0:1)]=v;}show("仅从USB耳机：左2秒、右2秒；不改系统音量");play(p,2,j);}else if(op.equals("roundtrip")||op.equals("auto-roundtrip")){if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=0)throw new IllegalStateException("RECORD_AUDIO permission required");show("仅采集USB麦克风5秒，请讲话；随后从USB耳机回放，不保存原始录音");short[] p=record(j);play(p,1,j);}else throw new IllegalArgumentException(op);j.put("pass",true);}catch(Exception e){try{j.put("pass",false);j.put("error",e.toString());}catch(Exception ignored){}}finally{busy=false;try{save(op,j);}catch(Exception e){show(e.toString());}}},"sq2-usb-public-api").start();}
 String read(String f){try(BufferedReader r=new BufferedReader(new FileReader(f))){return r.readLine();}catch(Exception e){return "unavailable";}}
 short[] record(JSONObject j)throws Exception{AudioDeviceInfo d=find(true);int min=AudioRecord.getMinBufferSize(48000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT);AudioRecord r=new AudioRecord.Builder().setAudioSource(MediaRecorder.AudioSource.MIC).setAudioFormat(new AudioFormat.Builder().setSampleRate(48000).setChannelMask(AudioFormat.CHANNEL_IN_MONO).setEncoding(AudioFormat.ENCODING_PCM_16BIT).build()).setBufferSizeInBytes(Math.max(min*4,19200)).build();try{if(r.getState()!=AudioRecord.STATE_INITIALIZED||(!j.optString("op").startsWith("auto-")&&!r.setPreferredDevice(d)))throw new IllegalStateException("USB record initialization/preference failed");short[] p=new short[240000];int n=0;long start=SystemClock.elapsedRealtime();r.startRecording();while(n<p.length&&!cancel&&SystemClock.elapsedRealtime()-start<7500){int k=r.read(p,n,Math.min(4800,p.length-n),AudioRecord.READ_NON_BLOCKING);if(k<0)throw new IOException("AudioRecord.read="+k);n+=k;if(k==0)Thread.sleep(5);}AudioDeviceInfo actual=r.getRoutedDevice();j.put("record_routed_id",actual==null?-1:actual.getId());j.put("record_routed_type",actual==null?-1:actual.getType());j.put("record_samples",n);j.put("record_ms",SystemClock.elapsedRealtime()-start);if(!usb(actual)||actual.getId()!=d.getId()||n!=p.length||cancel)throw new IllegalStateException("USB capture route/count failed");long square=0;int peak=0;for(short v:p){square+=(long)v*v;peak=Math.max(peak,Math.abs((int)v));}j.put("record_peak",peak);j.put("record_rms_dbfs",20*Math.log10(Math.max(1e-12,Math.sqrt(square/(double)p.length)/32768)));r.stop();return p;}finally{r.release();}}
 void play(short[] p,int channels,JSONObject j)throws Exception{AudioDeviceInfo d=find(false);AudioTrack t=new AudioTrack.Builder().setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build()).setAudioFormat(new AudioFormat.Builder().setEncoding(AudioFormat.ENCODING_PCM_16BIT).setSampleRate(48000).setChannelMask(channels==2?AudioFormat.CHANNEL_OUT_STEREO:AudioFormat.CHANNEL_OUT_MONO).build()).setBufferSizeInBytes(p.length*2).setTransferMode(AudioTrack.MODE_STATIC).build();try{int n=t.write(p,0,p.length,AudioTrack.WRITE_BLOCKING);if(n!=p.length)throw new IOException("AudioTrack.write="+n);j.put("play_state_after_write",t.getState());if(t.getState()!=AudioTrack.STATE_INITIALIZED||(!j.optString("op").startsWith("auto-")&&!t.setPreferredDevice(d)))throw new IllegalStateException("USB playback initialization/preference failed after static data write");t.play();Thread.sleep(150);AudioDeviceInfo actual=t.getRoutedDevice();j.put("play_routed_id",actual==null?-1:actual.getId());j.put("play_routed_type",actual==null?-1:actual.getType());if(!usb(actual)||actual.getId()!=d.getId())throw new IllegalStateException("USB output route failed");long start=SystemClock.elapsedRealtime();int expected=p.length/channels;while(t.getPlaybackHeadPosition()<expected&&!cancel&&SystemClock.elapsedRealtime()-start<expected*1000L/48000+2000)Thread.sleep(10);j.put("play_frames",t.getPlaybackHeadPosition());j.put("play_expected_frames",expected);if(cancel||t.getPlaybackHeadPosition()<expected)throw new IllegalStateException("USB playback incomplete");t.stop();}finally{t.release();}}
 protected void onDestroy(){cancel=true;super.onDestroy();}
}